from scenes import SCENES,eq,p,diagram,img,DDPM,LDM,LLADA,B,A,T,P

def app(i,title,lines,note,source=DDPM,visual=''):
 SCENES.append(dict(id=f'a{i:02}',number=i,title=title,section='Appendix',builds=len(lines),learning_goal=title,visual_description='Authored mathematical teaching construction',visual=visual,steps=lines,narration=note,question=title,answer=note,source=source,assets=[],layout='wide',routes=['appendix']))
app(1,'Independent Gaussians: means and variances', [eq(r'X\sim\mathcal N(m_x,v_x),\ Y\sim\mathcal N(m_y,v_y),\quad X\perp Y'),eq(r'aX+bY\sim\mathcal N(am_x+bm_y,a^2v_x+b^2v_y)'),p('Standard deviation scales by |a|; variance scales by a².')], 'Independence removes covariance cross terms. This is the algebra behind Scene 18. With alpha1=alpha2=.8, alpha2 beta1+beta2=.36, whose standard deviation is .6.')
app(2,'A lower bound on log evidence', [eq(r'\log p_\theta(x_0)=\log\mathbb E_{q(x_{1:T}|x_0)}\!\left[\frac{p_\theta(x_{0:T})}{q(x_{1:T}|x_0)}\right]'),eq(r'\log p_\theta(x_0)\geq\mathbb E_q[\log p_\theta(x_{0:T})-\log q(x_{1:T}|x_0)]'),eq(r'\log p_\theta(x_0)=\mathrm{ELBO}+D_{KL}(q(x_{1:T}|x_0)\Vert p_\theta(x_{1:T}|x_0))')], 'Jensen applies because log is concave. The posterior KL gap is nonnegative. The exact expectation is a lower bound; a single Monte Carlo realisation need not be below the evidence. This connects to the VAE derivation.')
app(3,'Factor the fixed chain backwards', [eq(r'q(x_{1:T}|x_0)=q(x_T|x_0)\prod_{t=2}^{T}q(x_{t-1}|x_t,x_0)'),eq(r'\mathcal L_{VLB}=D_{KL}(q(x_T|x_0)\Vert p(x_T))-\mathbb E_{q(x_1|x_0)}\log p_\theta(x_0|x_1)'),eq(r'\qquad+\sum_{t=2}^{T}\mathbb E_{q(x_t|x_0)}D_{KL}(q(x_{t-1}|x_t,x_0)\Vert p_\theta(x_{t-1}|x_t))')], 'Take the negative of the expected log ratio from A2 and use this reverse factorisation. The first term matches the terminal prior, each KL matches a local reverse, and the final likelihood reconstructs data. The endpoint likelihood for quantised pixels can integrate a continuous density over pixel bins; fixed zero posterior variance is not plugged into its log density.')
app(4,'The tractable training posterior', [eq(r'q(x_{t-1}|x_t,x_0)=\mathcal N(\tilde\mu_t,\tilde\beta_t I)'),eq(r'\tilde\mu_t=\frac{\sqrt{\bar\alpha_{t-1}}\beta_t}{1-\bar\alpha_t}x_0+\frac{\sqrt{\alpha_t}(1-\bar\alpha_{t-1})}{1-\bar\alpha_t}x_t'),eq(r'\tilde\beta_t=\beta_t\frac{1-\bar\alpha_{t-1}}{1-\bar\alpha_t}')], 'Multiply the forward transition Gaussian by the previous marginal and complete the square. Knowing x0 makes this Gaussian tractable. Integrating x0 under the data distribution generally yields a more complicated reverse conditional. Substituting xhat0 into this mean gives the epsilon-parameterised model mean.')
app(5,'Alternative prediction targets', [eq(r'v=\sqrt{\bar\alpha_t}\epsilon-\sqrt{1-\bar\alpha_t}x_0'),eq(r'x_0=\sqrt{\bar\alpha_t}x_t-\sqrt{1-\bar\alpha_t}v'),eq(r'\epsilon=\sqrt{1-\bar\alpha_t}x_t+\sqrt{\bar\alpha_t}v')], 'This is one explicit velocity convention. The two equations invert an orthogonal transformation of x0 and epsilon. Changing a prediction target also requires matching training, scheduler and checkpoint configuration. These equations do not imply all targets receive identical loss weights.',source='https://arxiv.org/abs/2202.00512')
app(6,'A faster sampler needs a different transition', [eq(r'f(t)=\cos^2\!\left(\frac{t/T+s}{1+s}\frac\pi2\right),\quad\bar\alpha_t=f(t)/f(0)'),eq(r'x_s=\sqrt{\bar\alpha_s}\hat x_0+\sqrt{1-\bar\alpha_s}\hat\epsilon\quad(s<t,\ \mathrm{DDIM}\ \eta=0)'),p('Linear / cosine schedule, respacing, DDIM and learned variance are separate choices.')], 'The deterministic DDIM expression is a separately defined sampler, not the original DDPM loop with arbitrary omissions. Improved DDPM uses a cosine schedule and learned-variance variants; beta clipping and exact endpoint conventions matter. The old course experiment uses a clipped cosine schedule; the new model uses the displayed 1000-step linear schedule.',source='https://arxiv.org/abs/2010.02502',visual=img('schedule.png','Actual linear training schedule; SNR uses a log axis and omits t=0'))
app(7,'A score oracle for eight Gaussian clusters', [eq(r'm_{k,t}=\sqrt{\bar\alpha_t}\mu_k,\quad v_t=\bar\alpha_t\tau^2+1-\bar\alpha_t'),eq(r'r_k=\operatorname{softmax}_k\!\left(-\frac{\|x-m_{k,t}\|^2}{2v_t}\right)'),eq(r'\nabla_x\log q_t(x)=\sum_k r_k\frac{m_{k,t}-x}{v_t},\quad\epsilon^*=-\sqrt{1-\bar\alpha_t}\nabla_x\log q_t(x)')], 'Centres lie on radius two and tau=.18. Use log-sum-exp stability. The exact score equals the conditional mean noise through this identity. The plotted Gaussian reverse steps remain a finite-step approximation; a true mixture reverse would sample component responsibilities and their conditional Gaussians. No network was trained for this oracle.')
app(8,'Flow matching: learn a velocity field', [eq(r'x_\tau=(1-\tau)x_{noise}+\tau x_{data},\quad u=x_{data}-x_{noise}'),eq(r'\min_\theta\ \mathbb E\|v_\theta(x_\tau,\tau)-u\|^2'),p('Generate by integrating dx/dτ = vθ(x,τ). This is a specified straight conditional path.')], 'This illustrative flow-matching setup uses independent endpoint pairs and a straight interpolation. The learned population velocity is a conditional expectation. It need not equal an individual pair velocity at an ambiguous point. It is related to probability transport but is not the epsilon DDPM objective or ancestral sampler.',source='https://arxiv.org/abs/2210.02747',visual=diagram([('Noise','τ=0',A),('Velocity field','learn transport',T),('Data','τ=1',B)]))
app(9,'Masked language: objective and sampling convention', [eq(r'\mathcal L=-\mathbb E_{t,x_0,x_t}\left[\frac1t\sum_i\mathbf1[x_t^i=MASK]\log p_\theta(x_0^i|x_t)\right]'),p('t is uniform on (0,1]; sum over modelled response positions. No sequence-length division here.'),p('Our scripted sampler: three response slots, reveal one per step, observed prompt fixed, no remasking.')], 'Each modelled position is independently masked with probability t. The 1/t weight is required for this LLaDA-style objective. A simple unweighted masked-position cross-entropy is pedagogical but is not numerically the same objective. Other samplers use confidence-based remasking and different length handling.',source=LLADA)
app(10,'Cross-attention with heads and spatial layout', [eq(r'[B,d_i,H,W]\to[B,N,d_i],\quad N=HW;\ C:[B,L,d_c]'),eq(r'Q:[B,h,N,d_k],\quad K:[B,h,L,d_k],\quad V:[B,h,L,d_v]'),eq(r'A:[B,h,N,L],\quad AV:[B,h,N,d_v]\to[B,N,hd_v]')], 'Merge heads, apply output projection, and restore the spatial layout. Softmax normalises L text positions for each image query in each head. Queries are image features; keys and values are text features in this selected block.',source=LDM)
app(11,'What to report with a generated example', [p('Published result: cite its actual condition, figure and supplied settings.'),p('Local result: dataset split, seed, checkpoint hash, target, schedule, sampler, budget.'),p('Research proposal: label it a possible task until validated against measurements.')], 'The new run is a 2000-step unconditional MNIST teaching model. The old guidance comparison is a separate 4000-step class-conditional checkpoint. There is no local text-to-image, DiT, satellite or language-model training. No FID or downstream improvement is asserted. Author-published image reuse requires a separate permissions review before external redistribution.',source='https://www.samarkhanna.com/DiffusionSat/')
